def draft(state):
    state["draft"] = f"Reply to: {state['ticket']}"
    state["attempts"] += 1
    return state

def review(state):
    state["approved"] = state["attempts"] >= 2        # reviewer wants one revision
    return state

def send(state):
    state["sent"] = True
    return state

nodes = {"draft": draft, "review": review, "send": send}
edges = {"draft": "review",
         "review": lambda s: "send" if s["approved"] else "draft",   # conditional edge
         "send": "END"}

state = {"ticket": "refund for order 9", "attempts": 0, "approved": False, "sent": False}
current, path = "draft", []
while current != "END":
    path.append(current)
    state = nodes[current](state)
    nxt = edges[current]
    current = nxt(state) if callable(nxt) else nxt
print(" -> ".join(path))
print(state)
